/**
 * Golden numerics tests for the TS Whisper log-mel port.
 *
 * Fixtures under /home/derek/hearsay-work/golden (override with GOLDEN_DIR)
 * were generated by golden_gen.py with HuggingFace transformers'
 * WhisperFeatureExtractor (do_normalize=True, chunk_length=8) plus
 * smart-turn-v3.2-cpu.onnx probabilities. The TS implementation must agree
 * elementwise below 1e-4. Tests skip when fixtures or the model are absent.
 */
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { describe, it } from "node:test";
import { computeWhisperMel } from "./whisper-mel.ts";

const GOLDEN_DIR = process.env.GOLDEN_DIR || "/home/derek/hearsay-work/golden";
const MODEL_PATH = process.env.SMART_TURN_MODEL_PATH || "/tmp/smart-turn-v3.2-cpu.onnx";
const CASES = ["silence", "sine_tail", "ramp"] as const;

type Npy = { data: Float32Array; shape: number[] };

/** Minimal .npy v1/v2 reader for little-endian float32/float64. */
function readNpy(path: string): Npy {
  const buf = readFileSync(path);
  const magic = buf.subarray(0, 6).toString("latin1");
  assert.equal(magic, "\x93NUMPY", `not a .npy file: ${path}`);
  let offset: number;
  if (buf[6] === 1) {
    offset = 10 + buf.readUInt16LE(8);
  } else {
    offset = 12 + buf.readUInt32LE(8);
  }
  const header = buf.subarray(10, offset).toString("latin1");
  const descr = /'descr':\s*'([<>=|]?)(\w+)'/.exec(header);
  const shape = /'shape':\s*\(([^)]*)\)/.exec(header);
  assert.ok(descr && shape, `unparsable npy header: ${header}`);
  const fortran = /'fortran_order':\s*True/.test(header);
  assert.equal(fortran, false, "fortran-order not supported");
  const dtype = descr[2];
  const dims = shape[1]
    .split(",")
    .map((s) => s.trim())
    .filter((s) => s.length > 0)
    .map(Number);
  const count = dims.reduce((a, b) => a * b, 1);
  let data: Float32Array;
  if (dtype === "f4") {
    data = new Float32Array(buf.buffer.slice(buf.byteOffset + offset, buf.byteOffset + offset + count * 4));
  } else if (dtype === "f8") {
    data = Float32Array.from(new Float64Array(buf.buffer.slice(buf.byteOffset + offset, buf.byteOffset + offset + count * 8)));
  } else {
    throw new Error(`unsupported dtype ${dtype}`);
  }
  return { data, shape: dims };
}

function goldenAvailable(): boolean {
  return existsSync(`${GOLDEN_DIR}/wav_silence.npy`) && existsSync(`${GOLDEN_DIR}/feats_silence.npy`);
}

describe("computeWhisperMel (golden fixtures)", { skip: !goldenAvailable() }, () => {
  for (const name of CASES) {
    it(`matches HF output for ${name}`, () => {
      const wav = readNpy(`${GOLDEN_DIR}/wav_${name}.npy`);
      const feats = readNpy(`${GOLDEN_DIR}/feats_${name}.npy`);
      const got = computeWhisperMel(wav.data);
      const want = feats.shape.length === 3 ? feats.data.subarray(0, feats.shape[1] * feats.shape[2]) : feats.data;
      assert.equal(got.length, want.length, "feature length mismatch");
      let maxDiff = 0;
      for (let i = 0; i < got.length; i++) {
        maxDiff = Math.max(maxDiff, Math.abs(got[i]! - want[i]!));
        if (maxDiff >= 1e-4) {
          assert.fail(`[${i}] got ${got[i]} want ${want[i]} (diff ${maxDiff})`);
        }
      }
      assert.ok(maxDiff < 1e-4, `max abs diff ${maxDiff} >= 1e-4`);
    });
  }

  it("output is finite float32 with values in [-1.5, ~1.5]", () => {
    const wav = readNpy(`${GOLDEN_DIR}/wav_ramp.npy`);
    const out = computeWhisperMel(wav.data);
    for (const v of out) assert.ok(Number.isFinite(v));
  });
});

describe("computeWhisperMel -> smart-turn model end-to-end", {
  skip: !(goldenAvailable() && existsSync(MODEL_PATH) && existsSync(`${GOLDEN_DIR}/manifest.json`)),
}, () => {
  const manifest = JSON.parse(readFileSync(`${GOLDEN_DIR}/manifest.json`, "utf8")) as
    Record<string, { probability: number }>;
  const expect: Record<string, number> = {
    silence: 0.987,
    sine_tail: 0.069,
    ramp: 0.98,
  };
  for (const name of Object.keys(expect)) {
    it(`model probability for ${name} is within 0.01 of ${expect[name]}`, async () => {
      const wav = readNpy(`${GOLDEN_DIR}/wav_${name}.npy`);
      const feats = computeWhisperMel(wav.data);
      const ort = await import("onnxruntime-node");
      const session = await ort.InferenceSession.create(readFileSync(MODEL_PATH), {
        graphOptimizationLevel: "all",
      });
      const tensor = new ort.Tensor("float32", feats, [1, 80, 800]);
      const out = await session.run({ input_features: tensor });
      const logit = (out["logits"] as { data: Float32Array }).data[0]!;
      assert.ok(Math.abs(logit - expect[name]!) < 0.01, `logit ${logit} vs expected ${expect[name]}`);
      assert.ok(Math.abs(logit - manifest[name]!.probability) < 0.01, `logit ${logit} vs manifest ${manifest[name]!.probability}`);
    });
  }
});
